from collections import Counter
def solve(A_):
    A_=np.array(A_); h,w=A_.shape
    cnt=Counter(int(x) for x in A_.ravel())
    # find unique hollow rectangle frames of ring color
    rings=[]
    for col in cnt:
        for r0 in range(h):
            for c0 in range(w):
                for H in range(3,h+1):
                    for W in range(3,w+1):
                        sub=A_[r0:r0+H,c0:c0+W]
                        b=np.concatenate([sub[0,:],sub[-1,:],sub[:,0],sub[:,-1]])
                        inn=sub[1:-1,1:-1]
                        if len(set(b.tolist()))==1 and b.tolist()[0]==col and (inn==0).all():
                            area=(H-2)*(W-2)
                            rings.append((area,col,r0,c0,H,W))
    rings.sort(key=lambda x:-x[0])
    out=A_.copy()
    placed=[]
    for area,col,r0,c0,H,W in rings:
        # choose placement maximizing cells painted (greedy), no overlap with already placed stamps
        def score(rr,cc):
            cells=sum(1 for i in range(H) for j in range(W) if i==0 or i==H-1 or j==0 or j==W-1 and out[rr+i,cc+j]!=col)
            return cells
        best=None;bestc=-1
        for rr in range(h-H+1):
            for cc in range(w-W+1):
                if (rr,cc) in [p[:2] for p in placed]: continue
                sc=score(rr,cc)
                if sc>bestc: bestc=sc; best=(rr,cc)
        if best is None: continue
        rr,cc=best
        placed.append((rr,cc,col,H,W))
        for i in range(H):
            for j in range(W):
                if i==0 or i==H-1 or j==0 or j==W-1:
                    out[rr+i,cc+j]=col
    return out.tolist()
